{-# LANGUAGE TemplateHaskell #-}
-- | The arXiv search helper that startup contexts point sessions at.
-- Upstream ships it in its repository; Fisher carries a copy (generated by
-- @tools/gen-defaults.py@) and installs it under the Fisher home.
module Fisher.Workflow.Arxiv (arxivScript, installArxivScript) where

import Control.Monad (unless)
import Data.ByteString (ByteString)
import qualified Data.ByteString as BS
import Data.FileEmbed (embedFile, makeRelativeToProject)
import System.Directory (createDirectoryIfMissing, doesFileExist)
import System.FilePath ((</>))

arxivScript :: ByteString
arxivScript = $(makeRelativeToProject "data/search_arxiv.py" >>= embedFile)

-- | Write the helper to @<home>/fisher/scripts/search_arxiv.py@ if it is
-- missing or differs, and return its path.
installArxivScript :: FilePath -> IO FilePath
installArxivScript home = do
  let dir = home </> "fisher" </> "scripts"
      path = dir </> "search_arxiv.py"
  createDirectoryIfMissing True dir
  exists <- doesFileExist path
  current <- if exists then BS.readFile path else pure BS.empty
  unless (current == arxivScript) (BS.writeFile path arxivScript)
  pure path
